  "Martin Rinkart · tr. Catherine Winkworth": { slug: "martin-rinkart", bio: "Martin Rinkart, or Rinckart was a German Lutheran clergyman and hymnist. He is best known for the text to \"Nun danket alle Gott\" which was written c. 1636. It was set to music by Johann Crüger about 1647, and translated into English in the 19th century by Catherine Winkworth.", article: "https://en.wikipedia.org/wiki/Martin_Rinkart" },
  "Matthias Claudius · tr. Jane Campbell": { slug: "matthias-claudius", bio: "Matthias Claudius was a German poet and journalist, otherwise known by the pen name of \"Asmus\".", article: "https://en.wikipedia.org/wiki/Matthias_Claudius" },
  "Medieval & Martin Luther · tr. composite": { slug: "medieval-martin-luther", bio: "Martin Luther was a German priest, theologian, author, hymnwriter, professor, and former Augustinian friar. Luther was the seminal figure of the Protestant Reformation, and his theological beliefs form the basis of Lutheranism. He is considered one of the most influential figures in Western and Christian history.", article: "https://en.wikipedia.org/wiki/Martin_Luther" },
  "Medieval & Martin Luther · tr. Richard Massie": { slug: "medieval-martin-luther", bio: "Martin Luther was a German priest, theologian, author, hymnwriter, professor, and former Augustinian friar. Luther was the seminal figure of the Protestant Reformation, and his theological beliefs form the basis of Lutheranism. He is considered one of the most influential figures in Western and Christian history.", article: "https://en.wikipedia.org/wiki/Martin_Luther" },
  "Nikolai Frederik Severin Grundtvig · tr. Carl D�ving": { slug: "nikolai-frederik-severin-grundtvig", bio: "Nikolaj Frederik Severin Grundtvig, most often referred to as N. F. S. Grundtvig, was a Danish pastor, author, poet, philosopher, historian, teacher and politician. He was one of the most influential people in Danish history, as his philosophy gave rise to a new form of nationalism in the last half of the 19th century.", article: "https://en.wikipedia.org/wiki/N._F._S._Grundtvig" },
  "Paul Gerhardt": { slug: "paul-gerhardt", bio: "Paulus or Paul Gerhardt was a German theologian, Lutheran pastor and hymnodist, considered Germany's greatest hymn writer. His songs and hymns were published in contemporary hymnals such as Praxis pietatis melica, and are still part of modern hymnals.", article: "https://en.wikipedia.org/wiki/Paul_Gerhardt" },
  "Paul Gerhardt · tr. Catherine Winkworth": { slug: "paul-gerhardt", bio: "Paulus or Paul Gerhardt was a German theologian, Lutheran pastor and hymnodist, considered Germany's greatest hymn writer. His songs and hymns were published in contemporary hymnals such as Praxis pietatis melica, and are still part of modern hymnals.", article: "https://en.wikipedia.org/wiki/Paul_Gerhardt" },
